INSERT INTO messages (id, text, "postedAt") VALUES
  ('44444444-0000-0000-0000-000000000001', 'Checkout error rate just went from 0.2% to 31%. Anyone touching payments right now?', '2026-03-14T09:12:00Z'),
  ('44444444-0000-0000-0000-000000000002', 'Nothing deployed since Tuesday. Pulling the dashboards.', '2026-03-14T09:14:00Z'),
  ('44444444-0000-0000-0000-000000000003', 'Support queue is filling up — about 40 tickets in ten minutes.', '2026-03-14T09:18:00Z'),
  ('44444444-0000-0000-0000-000000000004', 'Lock waits on the ledger are through the roof. This looks like the write path, not the gateway.', '2026-03-14T09:20:00Z'),
  ('44444444-0000-0000-0000-000000000005', 'Agreed — processor B is timing out and the retries are stacking. Tripping its breaker by hand.', '2026-03-14T09:27:00Z'),
  ('44444444-0000-0000-0000-000000000006', 'Breaker tripped, lock waits falling. Checkout recovering.', '2026-03-14T09:54:00Z'),
  ('44444444-0000-0000-0000-000000000007', 'Writing this up. The retry storm is the cause, the lock pile-up is the symptom.', '2026-03-16T10:00:00Z'),
  ('44444444-0000-0000-0000-000000000008', 'The runbook told us to do the right thing but three steps too late.', '2026-03-16T10:11:00Z'),
  ('44444444-0000-0000-0000-000000000009', 'Taking the retry cap. Per-processor, not global — global would starve the healthy ones.', '2026-03-17T14:05:00Z'),
  ('44444444-0000-0000-0000-000000000010', 'I will redo the lock-wait alert section so the breaker step comes first.', '2026-03-18T11:30:00Z'),
  ('44444444-0000-0000-0000-000000000011', 'Ping me when it is ready and I will run it past the on-call rota.', '2026-03-18T11:41:00Z')
